import {esc} from './weather-tools.js';
const topics={rain:'Piove lì adesso?',wind:'C’è vento forte lì?',cold:'Fa freddo lì?'};
export function createGrowth(ctx){
 const $=s=>document.querySelector(s),p=()=>ctx.get().place,stamp=t=>new Date(t).toLocaleTimeString('it-IT',{hour:'2-digit',minute:'2-digit'});let lastVerdict=null;
 const session=()=>ctx.api('sky/session',{}),status=t=>{if($('#growth-status'))$('#growth-status').textContent=t};
 async function gps(){return new Promise((resolve,reject)=>navigator.geolocation?navigator.geolocation.getCurrentPosition(r=>resolve({latitude:r.coords.latitude,longitude:r.coords.longitude,accuracy:r.coords.accuracy,locatedAt:r.timestamp,consent:true}),()=>reject(Error('Posizione non condivisa. Puoi comunque leggere le tue domande.')),{maximumAge:0,timeout:15000,enableHighAccuracy:true}):reject(Error('Posizione non disponibile.')))}
 async function zone(){await session();return (await ctx.api('growth/zone',{...p(),city:p().name})).zone}
 async function copy(url){try{await navigator.clipboard.writeText(url);ctx.toast('Link copiato.')}catch{ctx.modal('Copia il link',`<input aria-label="Link da copiare" readonly value="${esc(url)}">`,null)}}
 async function share(){try{const z=await zone();await copy(location.origin+'/z/'+z.slug)}catch(e){ctx.toast(e.message)}}
 function links(){return '<p><a href="#insieme">Chiedi a chi è lì · Organizza un evento · Confronto serale</a></p>'}
 function page(){return `<section><h1>Chiedi a chi è lì</h1><p>${esc(p().name)}</p><p id="growth-status" role="status"></p><p>Che tempo fa lì? Chiedilo a chi è fuori.</p><details class="info-disclosure"><summary aria-label="Come funzionano le domande">i</summary><p>Risposte anonime da chi condivide una posizione recente entro 5 km. La domanda scade dopo due ore.</p></details><div class="actions">${Object.entries(topics).map(([k,v])=>`<button data-question-topic="${k}">${v}</button>`).join('')}</div><button id="growth-nearby">Sono qui: domande vicine</button><button id="growth-refresh">Aggiorna risposte</button><div id="growth-questions" aria-live="polite"></div><details class="together-menu"><summary>Altro: eventi, confronto e condivisione</summary><h2>I miei eventi</h2><div id="my-events" aria-live="polite">Leggo i tuoi eventi…</div><h2>Un evento, lo stesso cielo</h2><p>Un invito privato per massimo 30 persone, senza chat. Si legge anche senza account e scade 24 ore dopo la giornata dell’evento.</p><form id="growth-event"><label class="field">Nome dell’evento<input id="event-name" required minlength="2" maxlength="60" placeholder="La nostra gita"></label><label class="field">Data nei prossimi sei giorni<input id="event-day" type="date" required></label><p>Luogo: ${esc(p().name)}. <a href="#mappa">Cambia città</a></p><button>Crea invito</button></form><div id="event-invite" role="status"></div><h2>Il confronto della sera</h2><p>Scopri come è cambiata la previsione di oggi.</p><details class="info-disclosure"><summary aria-label="Come funziona il confronto serale">i</summary><p>Conserviamo la previsione se apri questa città tra le 6 e le 8. Dalle 21 la confrontiamo con l’aggiornamento del modello, non con misure a terra.</p></details><button id="growth-verdict">Leggi il confronto</button><div id="growth-verdict-result" aria-live="polite"></div><h2>Il cielo della città, per tutti</h2><button id="growth-share">Copia il link vivo</button></details></section>`}
 function eventPage(){return '<section><h1>Il meteo del nostro evento</h1><p id="growth-status" role="status">Leggo l’invito…</p><div id="group-result" aria-live="polite"></div></section>'}
 async function questions(){await session();const [mine,nearby]=await Promise.all([ctx.api('questions/mine'),ctx.api('questions/nearby')]);const host=$('#growth-questions');if(!host)return;const notices=await ctx.api('questions/notifications');for(const n of notices.notifications)if(n.topic&&n.topic!=='school')await ctx.api('questions/seen',{id:n.id});const rows=[...new Map([...mine.questions,...nearby.questions].filter(r=>r.topic&&r.topic!=='school').map(r=>[r.id,r])).values()];host.innerHTML=rows.length?rows.map(r=>`<article><h3>${esc(topics[r.topic])} · ${esc(r.city)}</h3><p>Fino alle ${stamp(r.expires)} · ${r.own?'La tua domanda':'Dalla zona'}</p>${r.answers.length?r.answers.map(a=>`<p>${esc(a.answer)} · ${stamp(a.created)} <button data-answer-flag="${a.id}">Segnala abuso</button></p>`).join(''):'<p>Nessuna risposta per ora.</p>'}${r.own?'':`<div class="actions">${['Sì','No','Non so'].map(a=>`<button data-answer-question="${r.id}" data-answer="${a}">${a}</button>`).join('')}</div>`}</article>`).join(''):'<p>Scegli una domanda qui sopra.</p><div data-live-discovery></div>';
 host.querySelectorAll('[data-answer-question]').forEach(b=>b.onclick=()=>act(b,async()=>{const point=await gps();await ctx.api('questions/'+b.dataset.answerQuestion+'/answers',{...point,id:crypto.randomUUID(),answer:b.dataset.answer});status('La tua risposta è stata inviata a chi ha fatto la domanda.');await questions()}));host.querySelectorAll('[data-answer-flag]').forEach(b=>b.onclick=()=>act(b,async()=>{await ctx.api('questions/answers/'+b.dataset.answerFlag+'/flag',{});await questions();status('Risposta oscurata per la moderazione.')}));}
 async function act(button,fn){button.disabled=true;try{await fn()}catch(e){status(e.message)}finally{button.disabled=false}}
 async function verdict(){const z=await zone(),r=await ctx.api('growth/verdict?slug='+encodeURIComponent(z.slug));lastVerdict={...r,city:z.name};const host=$('#growth-verdict-result');if(!host)return;host.innerHTML=`<p>${esc(r.message)}</p>${r.status==='ready'?`<p><strong>${r.count} fasce cambiate su ${r.total} confrontabili.</strong></p>${r.rows.map(a=>`<p>${esc(a.time.slice(11))}: ${a.valid?`${a.before.temp}° → ${a.after.temp}° · ${a.before.rain} → ${a.after.rain} mm`:'dati incompleti'}</p>`).join('')}<button id="save-verdict">Salva l’immagine</button>`:''}`;$('#save-verdict')?.addEventListener('click',saveVerdict)}
 function saveVerdict(){const r=lastVerdict;if(r?.status!=='ready')return;const c=document.createElement('canvas');c.width=c.height=1080;const x=c.getContext('2d');x.fillStyle='#132441';x.fillRect(0,0,1080,1080);x.fillStyle='#f2f7fc';x.font='700 48px system-ui';x.fillText('MeteoSocial · Il confronto serale',60,100,960);x.font='400 38px system-ui';x.fillText(r.city,60,185,960);x.fillStyle='#4fb6f5';x.fillText(`${r.count} fasce cambiate su ${r.total}`,60,280,960);x.fillStyle='#f2f7fc';r.rows.forEach((a,i)=>x.fillText(`${a.time.slice(11)} · ${a.valid?a.before.temp+'° → '+a.after.temp+'°':'dati incompleti'}`,60,380+i*75,960));x.font='400 28px system-ui';x.fillText('Confronto tra aggiornamenti del modello Open-Meteo.',60,865,960);x.fillText('Non una misura degli errori con osservazioni a terra.',60,915,960);c.toBlob(b=>{if(!b)return;const url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download='meteosocial-confronto.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)})}
 async function group(){const params=new URLSearchParams(location.hash.split('?')[1]||''),id=params.get('id'),token=params.get('token');if(!id){status('Invito incompleto.');return}if(!token)await session();const r=await ctx.api('groups/'+encodeURIComponent(id)+'?token='+encodeURIComponent(token||'')),host=$('#group-result');if(!host)return;status('');host.innerHTML=`<h2>${esc(r.name)}</h2><p>${esc(r.city)} · ${esc(r.day)} · ${r.members}/30 partecipanti</p>${r.changed?'<p>La previsione è cambiata rispetto alla prima lettura. Ricontrolla gli orari qui sotto.</p>':''}<p>Controlliamo la previsione quando qualcuno apre l’evento. Puoi ricevere un solo avviso di cambiamento per evento, attivandolo nel Profilo. Senza consultazioni non parte un controllo automatico.</p>${r.forecast?`<p><strong>${r.forecast.rows.some(a=>Number.isFinite(a.rain)&&a.rain>.5)?'Portate un ombrello: il modello prevede pioggia in almeno una fascia.':r.forecast.rows.every(a=>Number.isFinite(a.rain))?'Nelle fasce mostrate il modello non prevede pioggia significativa. Ricontrollate prima di partire.':'Dati incompleti: non possiamo dare un consiglio affidabile.'}</strong></p><p>Modello Open-Meteo · aggiornato ${stamp(r.forecast.updated)}${r.forecast.stale?' · dati conservati, aggiornamento non riuscito':''}</p>${r.forecast.rows.map(a=>`<p>${a.time.slice(11)} · ${a.temp===null?'temperatura non disponibile':a.temp+'°'} · ${a.rain===null?'pioggia non disponibile':a.rain+' mm'}</p>`).join('')}`:'<p>Previsione non disponibile adesso.</p>'}<h3>Le persone lì, adesso</h3>${r.reports.length?r.reports.map(a=>`<p>${esc(a.phenomenon)} · ${stamp(a.created)}</p>`).join(''):'<p>Nessuna segnalazione nelle ultime due ore entro 5 km.</p>'}${r.joined?'<p>Partecipi a questo evento.</p>':'<button id="group-join">Partecipa</button>'}${token?'<button id="group-copy">Copia invito</button>':''}<p><a href="#insieme">I miei eventi</a> · <a href="#profilo">Preferenze avvisi</a></p>`;$('#group-copy')?.addEventListener('click',()=>copy(location.href));$('#group-join')?.addEventListener('click',e=>act(e.currentTarget,async()=>{await session();await ctx.api('groups/'+id+'/join',{token});await group()}))}
 async function myEvents(){await session();const r=await ctx.api('groups/mine'),host=$('#my-events');if(!host)return;host.innerHTML=r.groups.length?r.groups.map(g=>`<p><a href="#evento?id=${encodeURIComponent(g.id)}">${esc(g.name)} · ${esc(g.city)} · ${esc(g.day)}</a>${g.unread?' · Previsione cambiata':''}</p>`).join(''):'<p>Non partecipi ancora a un evento. Puoi crearne uno qui sotto o aprire un invito.</p>';}
 function humanSlot(){return '<div data-human-weather><p data-human-count aria-live="polite"></p><span>Fa freddo da te?</span> <button data-human-vote="yes">Sì</button> <button data-human-vote="no">No</button><p data-human-status role="status"></p></div>'}
 async function human(){const host=$('[data-human-weather]');if(!host)return;const place=p();const paint=r=>{if(host.isConnected)host.querySelector('[data-human-count]').textContent=r.total?`${r.cold} persone su ${r.total} entro 3 km dicono che fa freddo · ultime due ore.`:''};try{paint(await ctx.api('growth/human?'+new URLSearchParams({lat:place.latitude,lon:place.longitude})))}catch{}host.querySelectorAll('[data-human-vote]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await session();const point=await gps(),r=await ctx.api('growth/human',{...point,cold:b.dataset.humanVote==='yes'});host.querySelector('[data-human-status]').textContent='Risposta registrata nella zona in cui ti trovi.';if(Math.abs(point.latitude-place.latitude)<.01&&Math.abs(point.longitude-place.longitude)<.01)paint(r)}catch(e){host.querySelector('[data-human-status]').textContent=e.message}finally{b.disabled=false}})}
 function bind(){human();if($('#group-result'))group().catch(e=>status(e.message));if(!$('#growth-questions'))return;questions().catch(e=>status(e.message));myEvents().catch(()=>{if($('#my-events'))$('#my-events').textContent='Eventi non disponibili adesso. Riprova quando torna la connessione.'});$('#growth-share').onclick=share;$('#growth-verdict').onclick=e=>act(e.currentTarget,verdict);$('#growth-refresh').onclick=e=>act(e.currentTarget,questions);$('#growth-nearby').onclick=e=>act(e.currentTarget,async()=>{await session();await ctx.api('questions/presence',await gps());await questions();status('Mostro le domande entro 5 km dalla tua posizione.');});document.querySelectorAll('[data-question-topic]').forEach(b=>b.onclick=()=>act(b,async()=>{await session();const r=await ctx.api('questions',{...p(),city:p().name,id:crypto.randomUUID(),topic:b.dataset.questionTopic});await questions();status(r.people?`${r.people} persone hanno condiviso una presenza recente in zona.`:'Nessuno ha condiviso una presenza recente qui. La domanda resta aperta due ore; la risposta apparirà qui.')}));$('#growth-event').onsubmit=e=>{e.preventDefault();act(e.submitter,async()=>{await session();const r=await ctx.api('groups',{...p(),city:p().name,name:$('#event-name').value,day:$('#event-day').value});const url=location.origin+'/#evento?id='+r.id+'&token='+r.token;$('#event-invite').innerHTML=`<p>Invito pronto. Chi ha il link può leggere il gruppo.</p><a href="${esc(url)}">Apri evento</a>`;await copy(url);await myEvents()})}}
 async function restoreZone(){const slug=new URL(location.href).searchParams.get('zone');if(!slug)return;try{const r=await ctx.api('growth/zone?slug='+encodeURIComponent(slug));ctx.choose({name:r.zone.name,latitude:r.zone.lat/100,longitude:r.zone.lon/100});}catch(e){ctx.toast(e.message)}}
 async function morning(){const h=Number(new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Rome',hour:'2-digit',hourCycle:'h23'}).format(new Date()));if(h<6||h>=8)return;try{const z=await zone();await ctx.api('growth/verdict?slug='+z.slug)}catch{}}
 return {page,eventPage,bind,share,links,humanSlot,restoreZone,morning};
}
